<script setup>
import {computed,ref} from 'vue'
const props=defineProps({modelValue:{type:String,default:''},disabled:Boolean,kind:{type:String,default:'dbms'},suggestions:{type:Array,default:()=>[]}})
const emit=defineEmits(['update:modelValue','execute']),input=ref(null),highlight=ref(null)
const tokens=computed(()=>props.modelValue.split(/('(?:''|[^'])*'|`[^`]*`|"(?:\\.|[^"\\])*"|\b(?:SELECT|FROM|WHERE|ORDER|BY|GROUP|LIMIT|OFFSET|COUNT|MIN|MAX|SUM|AVG|AS|AND|OR|NOT|NULL|INSERT|UPDATE|DELETE|SET|VALUES|DESCRIBE|SHOW|TABLES|SCAN|MATCH|GET|HGET|HSCAN|LRANGE|SSCAN|ZSCAN|ZRANGE|TYPE|TTL|UNLINK|EXPIRE|HDEL)\b|\b\d+\b)/gi).filter(Boolean).map(text=>({text,kind:/^['"`]/.test(text)?'literal':/^\d+$/.test(text)?'number':/^[A-Z]+$/i.test(text)&&/^(SELECT|FROM|WHERE|ORDER|BY|GROUP|LIMIT|OFFSET|COUNT|MIN|MAX|SUM|AVG|AS|AND|OR|NOT|NULL|INSERT|UPDATE|DELETE|SET|VALUES|DESCRIBE|SHOW|TABLES|SCAN|MATCH|GET|HGET|HSCAN|LRANGE|SSCAN|ZSCAN|ZRANGE|TYPE|TTL|UNLINK|EXPIRE|HDEL)$/i.test(text)?'keyword':''})))
function syncScroll(){highlight.value.scrollTop=input.value.scrollTop;highlight.value.scrollLeft=input.value.scrollLeft}
function selected(){const el=input.value;return el&&el.selectionStart!==el.selectionEnd?props.modelValue.slice(el.selectionStart,el.selectionEnd):props.modelValue}
function insert(value){const el=input.value,start=el.selectionStart,end=el.selectionEnd;emit('update:modelValue',props.modelValue.slice(0,start)+value+props.modelValue.slice(end));el.focus()}
function format(){// Format whitespace only outside quoted values; never rewrite literals.
 const parts=props.modelValue.split(/('(?:''|[^'])*'|`[^`]*`|"(?:\\.|[^"\\])*")/g)
 emit('update:modelValue',parts.map((s,i)=>i%2?s:s.replace(/\s+/g,' ').replace(/\b(SELECT|FROM|WHERE|GROUP BY|ORDER BY|LIMIT|OFFSET|HAVING|UPDATE|SET|VALUES)\b/gi,(v)=>'\n'+v.toUpperCase())).join('').trim())
}
</script>
<template><div class="query-code"><div class="editor-tools"><small>{{kind==='dbms'?'SQL':'Redis'}} · Ctrl / ⌘ + Enter 执行选中内容或全文</small><button v-if="kind==='dbms'" type="button" :disabled="disabled" @click="format">格式化</button></div><div class="code-surface"><pre ref="highlight" aria-hidden="true"><span v-for="(token,i) in tokens" :key="i" :class="token.kind">{{token.text}}</span>{{'\n'}}</pre><textarea ref="input" :aria-label="kind==='dbms'?'查询 SQL':'查询命令（每行一条）'" :value="modelValue" :disabled="disabled" spellcheck="false" @input="emit('update:modelValue',$event.target.value)" @scroll="syncScroll" @keydown="e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();if(!disabled)emit('execute',selected())}}"/></div><div v-if="suggestions.length" class="completion"><small>字段：</small><button v-for="field in suggestions" :key="field" type="button" :disabled="disabled" @click="insert('`'+String(field).replaceAll('`','``')+'`')">{{field}}</button></div></div></template>
<style scoped>
.query-code{min-width:0}.editor-tools{display:flex;align-items:center;gap:12px;margin-bottom:6px}.editor-tools button{margin-left:auto;background:transparent;padding:3px 8px}.code-surface{position:relative;height:240px;min-height:140px;max-height:65vh;resize:vertical;overflow:hidden;border:1px solid var(--border);border-radius:8px;background:var(--input-bg)}pre,textarea{position:absolute;inset:0;width:100%;height:100%;margin:0;padding:12px!important;font:13px/1.7 var(--mono)!important;white-space:pre;tab-size:2;overflow:auto;border:0!important;border-radius:0!important;letter-spacing:0!important}pre{pointer-events:none;color:var(--text)}textarea{color:transparent!important;caret-color:var(--text);background:transparent!important;resize:none;outline:none}textarea:disabled{opacity:.6}.code-surface:focus-within{outline:2px solid var(--brand);outline-offset:1px}.keyword{color:var(--brand);font-weight:600}.literal{color:var(--ok)}.number{color:var(--warn)}.completion{display:flex;gap:4px;flex-wrap:wrap;margin-top:6px}.completion button{font:11px var(--mono);padding:3px 6px}
</style>
